;\\n}\\n\\nif (!rawText || rawText.length < 5) {\\n  throw new Error('EMPTY_RESPONSE');\\n}\\n\\n// STEP 2: CLEAN TEXT\\nrawText = rawText\\n  .replace(/```json/gi, '')\\n  .replace(/```/g, '')\\n  .replace(/\\\\r/g, '')\\n  .trim();\\n\\n// STEP 3: EXTRACT JSON BLOCK (VERY IMPORTANT)\\nconst jsonMatch = rawText.match(/\\\\{[\\\\s\\\\S]*\\\\}/);\\n\\nif (!jsonMatch) {\\n  console.log('❌ NO JSON FOUND:', rawText);\\n\\n  if (retryCount < MAX_RETRIES) {\\n    throw new Error(`RETRY_NO_JSON_${retryCount + 1}`);\\n  } else {\\n    throw new Error('FINAL_NO_JSON');\\n  }\\n}\\n\\nlet cleanJson = jsonMatch[0];\\n\\n// STEP 4: FIX COMMON JSON ISSUES\\ncleanJson = cleanJson\\n  .replace(/\\\\n/g, ' ')\\n  .replace(/\\\\t/g, ' ')\\n  .replace(/,\\\\s*}/g, '}') // trailing comma\\n  .replace(/,\\\\s*]/g, ']')\\n  .replace(/\\\\\\\\+\\"/g, '\\"')\\n  .replace(/\\"{2,}/g, '\\"')\\n  .trim();\\n\\n// STEP 5: AUTO-CLOSE JSON IF CUT\\nconst openBraces = (cleanJson.match(/{/g) || []).length;\\nconst closeBraces = (cleanJson.match(/}/g) || []).length;\\n\\nif (openBraces > closeBraces) {\\n  cleanJson += '}'.repeat(openBraces - closeBraces);\\n}\\n\\n// STEP 6: MULTI-TRY PARSE\\nlet parsed = null;\\n\\nconst tryParse = (text) => {\\n  try {\\n    return JSON.parse(text);\\n  } catch {\\n    return null;\\n  }\\n};\\n\\n// attempt 1\\nparsed = tryParse(cleanJson);\\n\\n// attempt 2 (remove weird chars)\\nif (!parsed) {\\n  parsed = tryParse(cleanJson.replace(/[^\\\\x20-\\\\x7E]+/g, ''));\\n}\\n\\n// attempt 3 (hard trim)\\nif (!parsed) {\\n  const shorter = cleanJson.substring(0, cleanJson.lastIndexOf('}') + 1);\\n  parsed = tryParse(shorter);\\n}\\n\\n// FINAL FAIL → RETRY\\nif (!parsed) {\\n  console.log('❌ FINAL RAW:', cleanJson);\\n\\n  if (retryCount < MAX_RETRIES) {\\n    throw new Error(`RETRY_PARSE_FAIL_${retryCount + 1}`);\\n  } else {\\n    throw new Error('FINAL_PARSE_FAILED');\\n  }\\n}\\n\\n// STEP 7: VALIDATE STRUCTURE\\nif (!parsed.prompt || !parsed.videoTitle || !parsed.videoDescription) {\\n\\n  console.log('⚠️ INVALID STRUCTURE:', parsed);\\n\\n  if (retryCount < MAX_RETRIES) {\\n    throw new Error(`RETRY_INVALID_STRUCTURE_${retryCount + 1}`);\\n  } else {\\n    throw new Error('FINAL_INVALID_STRUCTURE');\\n  }\\n}\\n\\n// STEP 8: SUCCESS OUTPUT\\nconst now = new Date();\\n\\nreturn [{\\n  json: {\\n    prompt: parsed.prompt,\\n    videoTitle: parsed.videoTitle,\\n    videoDescription: parsed.videoDescription,\\n    generatedAt: now.toISOString(),\\n    dateLabel: now.toISOString().split('T')[0],\\n    fileName: 'jelly-asmr-' + now.toISOString().split('T')[0] + '.mp4',\\n    retryCount,\\n    status: 'success'\\n  }\\n}];","",["68"],["69"],["70"],"Gemini – Generate Prompt",{"content":"71","finishReason":"72","index":0},["73"],{"json":"44","pairedItem":"74"},{"json":"75","pairedItem":"76"},{"json":"44","pairedItem":"77"},{"parts":"78","role":"79"},"STOP",{"modality":"80","tokenCount":86},{"item":0},{"timestamp":"81","Readable date":"82","Readable time":"83","Day of week":"84","Year":"85","Month":"86","Day of month":"87","Hour":"88","Minute":"89","Second":"90","Timezone":"91"},{"item":0},{"item":0},["92","93"],"model","TEXT","2026-04-21T03:58:11.612-04:00","April 21st 2026, 3:58:11 am","3:58:11 am","Tuesday","2026","April","21","03","58","11","America/New_York (UTC-04:00)",{"text":"94","thought":true},{"text":"95"},"*   Goal: Generate a viral ASMR vertical video concept.\\n    *   Output format: Valid, parseable JSON.\\n    *   Required fields: `prompt`, `videoTitle`, `videoDescription`.\\n    *   Constraints: No explanations, no markdown, no backticks, no comments, must start with `{` and end with `}`.\\n\\n    *   Concept: Kinetic sand slicing or honeycomb crushing? Let's go with something visually satisfying and high-contrast.\\n    *   Scene: A macro shot of a crystal-clear honey block being slowly sliced by a heated knife, with iridescent glitter embedded inside.\\n    *   Title: \\"Forbidden Honey Slicing 🍯✨\\"\\n    *   Description: \\"The most satisfying slice you'll see today. 🤤 #ASMR #Satisfying #OddlySatisfying\\"\\n\\n    *   `prompt`: \\"A hyper-realistic, macro vertical shot of a translucent, gold-colored honeycomb block embedded with iridescent holographic glitter. A glowing, heated titanium knife slowly sinks through the block, creating a clean melt and slow-motion drips of thick syrup. Soft, warm cinematic lighting with high contrast and deep shadows.\\"\\n    *   `videoTitle`: \\"Forbidden Honey Slicing 🍯✨\\"\\n    *   `videoDescription`: \\"Wait for the drip... 🤤 The most satisfying slice you'll see today. #ASMR #Satisfying #OddlySatisfying\\"\\n\\n    *   Is it valid JSON? Yes.\\n    *   Are strings double-quoted? Yes.\\n    *   Are there backticks? No.\\n    *   Is there extra text? No.","{\\n  \\"prompt\\": \\"A hyper-realistic, macro vertical shot of a translucent, gold-colored honeycomb block embedded with iridescent holographic glitter. A glowing, heated titanium knife slowly sinks through the block, creating a clean melt and slow-motion drips of thick syrup. Soft, warm cinematic lighting with high contrast and deep shadows.\\",\\n  \\"videoTitle\\": \\"Forbidden Honey Slicing 🍯✨\\",\\n  \\"videoDescription\\": \\"Wait for the drip... 🤤 The most satisfying slice you'll see today. #ASMR #Satisfying #OddlySatisfying\\"\\n}"]	80020869-ce0e-479d-bedc-100cad309877
