 parsed = null;\\n\\nconst tryParse = (text) => {\\n  try {\\n    return JSON.parse(text);\\n  } catch {\\n    return null;\\n  }\\n};\\n\\n// attempt 1\\nparsed = tryParse(cleanJson);\\n\\n// attempt 2 (remove weird chars)\\nif (!parsed) {\\n  parsed = tryParse(cleanJson.replace(/[^\\\\x20-\\\\x7E]+/g, ''));\\n}\\n\\n// attempt 3 (hard trim)\\nif (!parsed) {\\n  const shorter = cleanJson.substring(0, cleanJson.lastIndexOf('}') + 1);\\n  parsed = tryParse(shorter);\\n}\\n\\n// FINAL FAIL → RETRY\\nif (!parsed) {\\n  console.log('❌ FINAL RAW:', cleanJson);\\n\\n  if (retryCount < MAX_RETRIES) {\\n    throw new Error(`RETRY_PARSE_FAIL_${retryCount + 1}`);\\n  } else {\\n    throw new Error('FINAL_PARSE_FAILED');\\n  }\\n}\\n\\n// STEP 7: VALIDATE STRUCTURE\\nif (!parsed.prompt || !parsed.videoTitle || !parsed.videoDescription) {\\n\\n  console.log('⚠️ INVALID STRUCTURE:', parsed);\\n\\n  if (retryCount < MAX_RETRIES) {\\n    throw new Error(`RETRY_INVALID_STRUCTURE_${retryCount + 1}`);\\n  } else {\\n    throw new Error('FINAL_INVALID_STRUCTURE');\\n  }\\n}\\n\\n// STEP 8: SUCCESS OUTPUT\\nconst now = new Date();\\n\\nreturn [{\\n  json: {\\n    prompt: parsed.prompt,\\n    videoTitle: parsed.videoTitle,\\n    videoDescription: parsed.videoDescription,\\n    generatedAt: now.toISOString(),\\n    dateLabel: now.toISOString().split('T')[0],\\n    fileName: 'jelly-asmr-' + now.toISOString().split('T')[0] + '.mp4',\\n    retryCount,\\n    status: 'success'\\n  }\\n}];","",["68"],["69"],["70"],"Gemini – Generate Prompt1",{"content":"71","finishReason":"72","index":0},["73"],{"json":"44","pairedItem":"74"},{"json":"75","pairedItem":"76"},{"json":"44","pairedItem":"77"},{"parts":"78","role":"79"},"STOP",{"modality":"80","tokenCount":86},{"item":0},{"timestamp":"81","Readable date":"82","Readable time":"83","Day of week":"84","Year":"85","Month":"86","Day of month":"87","Hour":"88","Minute":"89","Second":"90","Timezone":"91"},{"item":0},{"item":0},["92","93"],"model","TEXT","2026-04-21T11:09:24.980-04:00","April 21st 2026, 11:09:24 am","11:09:24 am","Tuesday","2026","April","21","11","09","24","America/New_York (UTC-04:00)",{"text":"94","thought":true},{"text":"95"},"*   Goal: Generate a viral ASMR vertical video concept.\\n    *   Format: Valid, parseable JSON.\\n    *   Fields: `prompt` (detailed visual scene), `videoTitle` (viral short title), `videoDescription` (engaging description).\\n    *   Constraints: No explanations, no markdown, no backticks, no comments, no extra text, must be a single JSON object.\\n\\n    *   Visual scene: High-quality close-up of kinetic sand being sliced with a heated knife or a precision cutter. Vibrant colors (neon purple and teal). Slow motion. Macro lens.\\n    *   Title: Satisfying Neon Sand Slices 🌈\\n    *   Description: Wait for the end! The most satisfying sound you'll hear today. #ASMR #Satisfying #KineticSand\\n\\n    *   `prompt`: \\"Extreme macro close-up of a neon purple and teal gradient kinetic sand block. A sharp, heated stainless steel knife slowly slices through the sand in thin, precise layers. The sand crumbles in slow motion, revealing a shimmering crystalline interior. Soft, diffused studio lighting with deep shadows to emphasize texture.\\"\\n    *   `videoTitle`: \\"Oddly Satisfying Neon Slices 🌈\\"\\n    *   `videoDescription`: \\"The crunch you've been waiting for. 🎧 Wear headphones for the full experience! #ASMR #Satisfying #KineticSand\\"\\n\\n    *   JSON valid? Yes.\\n    *   Parseable? Yes.\\n    *   Strings quoted? Yes.\\n    *   No markdown/backticks? Yes.\\n    *   No extra text? Yes.","{\\n  \\"prompt\\": \\"Extreme macro close-up of a neon purple and teal gradient kinetic sand block. A sharp, heated stainless steel knife slowly slices through the sand in thin, precise layers. The sand crumbles in slow motion, revealing a shimmering crystalline interior. Soft, diffused studio lighting with deep shadows to emphasize texture.\\",\\n  \\"videoTitle\\": \\"Oddly Satisfying Neon Slices 🌈\\",\\n  \\"videoDescription\\": \\"The crunch you've been waiting for. 🎧 Wear headphones for the full experience! #ASMR #Satisfying #KineticSand\\"\\n}"]	a7e4cb2c-7c9c-4ca4-8339-db9f05f1ce63
