w!","additionalFields":{"parse_mode":"Markdown"}},"id":"156cfc32-9272-4a0e-8f24-3fefca823555","name":"Telegram – Notify Me1","type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[848,2224],"webhookId":"c4d4b89f-46d2-4196-886f-7d37b057fbe9","credentials":{"telegramApi":{"id":"TaENrfhW5rgx9oJQ","name":"Telegram account"}}},{"parameters":{"rule":{"interval":[{"field":"hours","hoursInterval":24}]}},"id":"0b03cfb3-586a-4876-b81e-a97be7dc4f8e","name":"Schedule Trigger3","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.2,"position":[-816,1936]},{"parameters":{"functionCode":"return [{ json: { retryCount: 0 } }];"},"id":"a47f6927-7686-4366-810b-61f28e13211b","name":"Init Retry","type":"n8n-nodes-base.function","typeVersion":1,"position":[-592,1936]}]	{"Schedule Trigger":{"main":[[{"node":"Generate Prompt","type":"main","index":0}]]},"Structured Output Parser":{"ai_outputParser":[[{"node":"Generate Prompt","type":"ai_outputParser","index":0}]]},"Google Gemini Chat Model":{"ai_languageModel":[[{"node":"Generate Prompt","type":"ai_languageModel","index":0}]]},"Generate Prompt":{"main":[[{"node":"Secret Payload","type":"main","index":0}]]},"Secret Payload":{"main":[[{"node":"JWT","type":"main","index":0}]]},"JWT":{"main":[[{"node":"HTTP Request","type":"main","index":0}]]},"Gemini – Generate Prompt":{"main":[[{"node":"Parse Gemini JSON","type":"main","index":0}]]},"Parse Gemini JSON":{"main":[[{"node":"Kling AI – Submit Video","type":"main","index":0}]]},"Kling AI – Submit Video":{"main":[[{"node":"Store Task ID","type":"main","index":0}]]},"Store Task ID":{"main":[[{"node":"Wait 5 Min","type":"main","index":0}]]},"Wait 5 Min":{"main":[[{"node":"Kling AI – Poll Status","type":"main","index":0}]]},"Kling AI – Poll Status":{"main":[[{"node":"Video Ready?","type":"main","index":0}]]},"Video Ready?":{"main":[[{"node":"Extract Video URL","type":"main","index":0}],[{"node":"Wait 3 Min Retry","type":"main","index":0}]]},"Wait 3 Min Retry":{"main":[[{"node":"Kling AI – 